-- r06_commit_ts, node 1. Generated by gen.py from special/src/r06_commit_ts.sql.
-- Usage:  psql -X -q -v ON_ERROR_STOP=1 -d <database> -f r06_commit_ts_node1.sql
--
-- Case R6: commit timestamps and replication origins of the rows.
-- Stand: both servers with track_commit_timestamp = on (needs a restart).
--        The script fails at once if the setting is off.
-- Run:   node 1 and node 2 scripts in the two databases.
-- Expect (pick_freshest, --preserve-origin, --until):
--   row 1: node 1 wrote it now, node 2 holds an old version from the origin
--          ace_ref_peer (commit time 2020-01-01): the fresher side is node 1.
--   row 2: the opposite: the fresher side is node 2.
--   row 3: both versions come from an origin, with commit times 2021 / 2022:
--          the fresher side is node 2.
--   row 4: only on node 1, from the origin ace_ref_peer: a repair with
--          --preserve-origin must keep this origin and the time 2020-06-01.
--   sp.r06_frozen: the rows of node 1 are frozen; row 2 differs. On PG 18 a
--          frozen row still shows its commit time. The time becomes NULL only
--          when the server has cut the old commit timestamp data, which this
--          script cannot force. So check both: a filter by commit time
--          (--until) must keep frozen rows, and pick_freshest must not crash
--          on a NULL time.
--   Check: SELECT id, v, pg_xact_commit_timestamp(xmin), (pg_xact_commit_timestamp_origin(xmin)).roident
--          FROM sp.r06_origin ORDER BY id;

SET client_min_messages = warning;
SET TimeZone = 'UTC';
SET DateStyle = 'ISO, MDY';
SET IntervalStyle = 'postgres';
SET default_transaction_read_only = off;
CREATE SCHEMA IF NOT EXISTS sp;
DO $$
BEGIN
	IF current_setting('track_commit_timestamp') <> 'on' THEN
		RAISE EXCEPTION 'this case needs track_commit_timestamp = on';
	END IF;
	IF NOT EXISTS (SELECT FROM pg_replication_origin WHERE roname = 'ace_ref_peer') THEN
		PERFORM pg_replication_origin_create('ace_ref_peer');
	END IF;
END $$;
DROP TABLE IF EXISTS sp.r06_origin, sp.r06_frozen;
CREATE TABLE sp.r06_origin (id int PRIMARY KEY, v text);
CREATE TABLE sp.r06_frozen (id int PRIMARY KEY, v text);
INSERT INTO sp.r06_origin VALUES (0, 'same, local on both');
INSERT INTO sp.r06_origin VALUES (1, 'row 1: new local version of node 1');
DO $$ BEGIN
	PERFORM pg_replication_origin_session_setup('ace_ref_peer');
	PERFORM pg_replication_origin_xact_setup('0/1', '2020-01-01 00:00:00+00');
	INSERT INTO sp.r06_origin VALUES (2, 'row 2: old version from the peer');
END $$;
DO $$ BEGIN
	PERFORM pg_replication_origin_xact_setup('0/2', '2021-01-01 00:00:00+00');
	INSERT INTO sp.r06_origin VALUES (3, 'row 3: version of 2021');
END $$;
DO $$ BEGIN
	PERFORM pg_replication_origin_xact_setup('0/3', '2020-06-01 00:00:00+00');
	INSERT INTO sp.r06_origin VALUES (4, 'row 4: only on node 1, from the peer');
END $$;
DO $$ BEGIN PERFORM pg_replication_origin_session_reset(); END $$;
INSERT INTO sp.r06_frozen VALUES (1, 'same'), (2, 'frozen on node 1');
VACUUM (FREEZE) sp.r06_frozen;
COMMENT ON TABLE sp.r06_origin IS 'R6: rows 1-3 changed, row 4 only on node 1; the fresher side is node 1 for row 1 and node 2 for rows 2, 3';
COMMENT ON TABLE sp.r06_frozen IS 'R6: row 2 changed; the rows of node 1 are frozen';
